B.dg={Operation:0}
B.a_A=new A.b8(B.dg,["Converts 4-bit binary (0-15) to 7-segment display pattern.\n0-9: Numeric digits; 10-15: Hexadecimal A-F.\n\nConnect outputs to 7-segment display component.\n"],t.l)
B.Pv=new A.cy("7-Segment\nDecoder","The **7-segment decoder** converts a **4-bit binary** input into a **7-segment** display pattern.\n\nAutomatically maps 0-9 to their display representations.\n",B.a_A)
B.a_H=new A.b8(B.dg,["**Matrix Scanning:** \n- When a column input (C0-C3) is HIGH and a key is pressed,\n  the corresponding row output (R0-R3) becomes HIGH.\n- Scan columns sequentially to detect which key is pressed.\n\nC0  C1  C2  C3\n[1] [2] [3] [A] R0\n[4] [5] [6] [B] R1\n[7] [8] [9] [C] R2\n[*] [0] [#] [D] R3\n"],t.l)
B.t9=new A.cy("4\xd74 Matrix Keypad","A **4\xd74 matrix keypad** for user input with row and column scanning.\n\nFeatures 16 keys arranged in 4 rows and 4 columns.\nKeys: 0-9, A-D, *, #\n",B.a_H)
B.a_z=new A.b8(B.dg,["CLK rising edge:\n- J=1, K=0: Q = 1 (set)\n- J=0, K=1: Q = 0 (reset)\n- J=0, K=0: Q unchanged (hold)\n- J=1, K=1: Q toggles\n\nRST = 1: Q = 0 (asynchronous clear).\nNo undefined state (unlike SR flip-flop).\n"],t.l)
B.Pw=new A.cy("JK Flip-Flop","Universal flip-flop combining set, reset, hold, and toggle operations without undefined states.\n\nJ=K=1 toggles output, eliminating the SR flip-flop's undefined condition.\nMost versatile flip-flop type for counters, state machines, and general applications.\n",B.a_z)
B.a_B=new A.b8(B.dg,["Each input (A-G) controls one segment; DP controls decimal point.\nHIGH = segment illuminated; LOW = segment off.\nEN = master enable/disable.\n\nUse 7-segment decoder for automatic digit conversion.\n"],t.l)
B.ta=new A.cy("7-Segment Display","Displays digits 0-9 and hexadecimal A-F using seven segments arranged in figure-8 pattern.\n\nSegments A-G are independently controlled; DP provides decimal point.\nCommonly used in digital clocks, meters, and calculators.\n",B.a_B)
B.a_G=new A.b8(B.dg,["Displays input signal state visually.\nY = A (pass-through)\n\nVisual indicator reflects input level.\n"],t.l)
B.tb=new A.cy("Output","Displays signal state visually for monitoring and debugging.\n\nReal-time indicator reflects input signal level.\nUseful for verifying circuit outputs and signal tracing.\n",B.a_G)
B.a0Q={Inputs:0,Outputs:1,Operation:2}
B.a06=new A.b8(B.a0Q,["EN (Enable)","D0-D7 (ASCII), STR (Strobe)","  **Enable**: Set EN high to capture all keyboard input.\n  **D0-D7** outputs the ASCII code.\n  **STR** high pulse when key pressed.\n"],t.l)
B.tc=new A.cy("Keyboard Input","Captures keyboard input and outputs ASCII codes when **EN** pin is high.\n\nOutputs 8-bit ASCII data and a Strobe pulse on key press.\n",B.a06)
B.a_D=new A.b8(B.dg,["CLK rising edge: Q = D (captures input); ~Q = NOT D.\nRST = 1: Q = 0 (asynchronous clear; overrides clock).\nOtherwise: Q retains previous value.\n\nStores one bit synchronized to clock edge.\n"],t.l)
B.Px=new A.cy("D Flip-Flop","Captures and stores data input on clock rising edge.\n\nOutput follows input only at clock transition, providing synchronization and immunity to glitches.\nMost common flip-flop type for data storage, shift registers, and delay lines.\n",B.a_D)
B.a_F=new A.b8(B.dg,["CLK rising edge:\n- S=1, R=0: Q = 1 (set)\n- S=0, R=1: Q = 0 (reset)\n- S=0, R=0: Q unchanged (hold)\n- S=1, R=1: Undefined (avoid)\n\nRST = 1: Q = 0 (asynchronous clear).\n"],t.l)
B.Py=new A.cy("SR Flip-Flop","Provides independent set and reset control synchronized to clock edge.\n\nS=1 sets output HIGH, R=1 resets to LOW, both LOW holds state.\nAvoid S=R=1 condition (undefined state).\n\nUseful for control logic and basic memory elements.\n",B.a_F)
B.a_C=new A.b8(B.dg,["CLK rising edge:\n- T = 1: Q toggles (0\u21921 or 1\u21920)\n- T = 0: Q unchanged\n\nRST = 1: Q = 0 (asynchronous clear; overrides clock).\n~Q is always complement of Q.\n\nActs as frequency divider when T = 1.\n"],t.l)
B.Pz=new A.cy("T Flip-Flop","Toggles output on clock rising edge when T=1; holds state when T=0.\n\nProvides frequency division (divides by 2 when T=1) and self-complementing behavior.\nCommonly used in frequency dividers and binary counters.\n",B.a_C)
B.a_E=new A.b8(B.dg,["EN = 1: Y = A (output actively drives signal).\nEN = 0: Y = High-Z (output disconnected; neither sources nor sinks current).\n\nMultiple tri-state buffers can share the same bus line.\n"],t.l)
B.PA=new A.cy("Tri-State\nBuffer","Controls signal flow with three output states: HIGH, LOW, and High-Z (high impedance).\n\nWhen enabled, passes input to output.\nWhen disabled, output enters High-Z state (disconnected).\n\nMultiple buffers can share the same bus by using High-Z state.\n",B.a_E)
